{"code":"function handleSendMessage(e) {
    e.preventDefault();
    const msg = input.value.trim();
    const mdl = model.value;
    if (!msg) return;
    input.value = '';
    // Show user message immediately
    renderMessage('user', msg);
    // Stream request to backend
    fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: msg, model: mdl })
    }).then(async response => {
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let assistantMsg = '';
        while (true) {
            const { done, value } = await reader.read();
            if (done) {
                if (assistantMsg.trim()) {
                    renderMessage('assistant', assistantMsg.trim());
                }
                break;
            }
            // Each chunk is a JSON string
            const chunkStr = decoder.decode(value);
            try {
                const lines = chunkStr.split('\n').filter(Boolean);
                for (const line of lines) {
                    const data = JSON.parse(line);
                    if (data.message && data.message !== '[DONE]') {
                        assistantMsg += data.message;
                    }
                }
            } catch (err) {
                // Ignore parse errors for incomplete chunks
            }
        }
    });
}
