{% block content %}
<div class="container mt-4">
  <h2>Add Model</h2>
  <form id="add-model-form" class="mb-4">
    <div class="mb-3">
      <label for="api-host" class="form-label">API Host</label>
      <select class="form-select" id="api-host" name="api-host">
        <option value="ollama" selected>Ollama</option>
        <option value="openai">OpenAI</option>
      </select>
    </div>
    <div class="mb-3">
      <label for="api-url" class="form-label">URL</label>
      <input type="text" class="form-control" id="api-url" name="api-url" placeholder="http://rpi.netbird.cloud:11434" />
    </div>
    <div class="mb-3" id="api-key-group" style="display:none;">
      <label for="api-key" class="form-label">API Key</label>
      <input type="text" class="form-control" id="api-key" name="api-key" placeholder="sk-..." />
    </div>
    <button type="button" class="btn btn-success" id="fetch-model-btn">Fetch</button>
  </form>
  <div id="models-table-container"></div>
</div>
<script>
document.getElementById('api-host').addEventListener('change', function() {
  var keyGroup = document.getElementById('api-key-group');
  keyGroup.style.display = this.value === 'openai' ? '' : 'none';
});

document.getElementById('fetch-model-btn').addEventListener('click', function() {
  const host = document.getElementById('api-host').value;
  const url = document.getElementById('api-url').value;
  const key = document.getElementById('api-key').value;
  const modelsTableContainer = document.getElementById('models-table-container');
  modelsTableContainer.innerHTML = '<div class="text-center my-3"><span class="spinner-border" role="status"></span> Fetching models...</div>';
  fetch('/fetch', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ host, url, key })
  })
  .then(res => res.json())
  .then(data => {
    if (data.status === 'success' && Array.isArray(data.models)) {
      let html = `<table class="table table-bordered align-middle mt-3"><thead><tr><th>Nickname</th><th>Model</th><th>Vision</th><th>Reasoning</th><th>Tools</th></tr></thead><tbody>`;
      data.models.forEach(model => {
        html += `<tr>
          <td>${model.nickname}</td>
          <td>${model.model}</td>
          <td>${model.vision ? 'Yes' : 'No'}</td>
          <td>${model.reasoning ? 'Yes' : 'No'}</td>
          <td>${model.tools ? 'Yes' : 'No'}</td>
        </tr>`;
      });
      html += '</tbody></table>';
      modelsTableContainer.innerHTML = html;
    } else {
      modelsTableContainer.innerHTML = '<div class="text-danger mt-3">No models found or error.</div>';
    }
  })
  .catch(err => {
    modelsTableContainer.innerHTML = '<div class="text-danger mt-3">API error.</div>';
    console.error('API error:', err);
  });
});
</script>
{% endblock %}
","explanation":"Updated add_model.html to provide API host selection, URL and key input, and fetch models using the /fetch API. Results are displayed in a table."}

